import java.sql.*; import java.util.*;
public class MemberDAO {
 public boolean addMember(Member m)throws SQLException{return save("INSERT INTO members(name,department,phone) VALUES(?,?,?)",m,false);} public boolean updateMember(Member m)throws SQLException{return save("UPDATE members SET name=?,department=?,phone=? WHERE member_id=?",m,true);}
 private boolean save(String q,Member m,boolean u)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setString(1,m.getName());p.setString(2,m.getDepartment());p.setString(3,m.getPhone());if(u)p.setInt(4,m.getMemberId());return p.executeUpdate()==1;}}
 public List<Member> getAllMembers()throws SQLException{return find("SELECT * FROM members ORDER BY member_id",null);} public List<Member> searchMembers(String q)throws SQLException{return find("SELECT * FROM members WHERE name LIKE ? OR phone LIKE ? ORDER BY name",q);} public Member getMemberById(int id)throws SQLException{List<Member>x=find("SELECT * FROM members WHERE member_id=?",id);return x.isEmpty()?null:x.get(0);} private List<Member> find(String q,Object v)throws SQLException{List<Member>x=new ArrayList<>();try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){if(v instanceof Integer)p.setInt(1,(Integer)v);else if(v!=null){p.setString(1,"%"+v+"%");p.setString(2,"%"+v+"%");}try(ResultSet r=p.executeQuery()){while(r.next())x.add(new Member(r.getInt("member_id"),r.getString("name"),r.getString("department"),r.getString("phone")));}}return x;}
}
